<?php
namespace App\Controllers;
use App\Models\StudentAuditLogModel; use App\Models\StudentModel; use CodeIgniter\Exceptions\PageNotFoundException; use Config\Database; use DomainException;
final class StudentManagementController extends BaseController { protected $helpers=['form','url'];
 public function index(): string {$m=new StudentModel();$q=trim((string)$this->request->getGet('q'));$status=(string)$this->request->getGet('status');if($q!=='')$m->groupStart()->like('student_id',$q)->orLike('full_name',$q)->orLike('institutional_email',$q)->orLike('program',$q)->orLike('department',$q)->groupEnd();if(in_array($status,['enrolled','not_enrolled'],true))$m->where('enrollment_status',$status);return view('students/index',['title'=>'Students','students'=>$m->orderBy('created_at','DESC')->orderBy('id','DESC')->paginate(15),'pager'=>$m->pager,'q'=>$q,'status'=>$status]);}
 public function create(): string{return $this->form([],'Create student');} public function store(){return $this->save(null);} public function show(int $id): string{return $this->form($this->student($id),'Student record',true);} public function edit(int $id): string{return $this->form($this->student($id),'Edit student');} public function update(int $id){$this->student($id);return $this->save($id);}
 private function save(?int $id){$input=$this->input();try{$this->validateInput($input,$id);$db=Database::connect();$db->transException(true)->transBegin();try{$m=new StudentModel();$before=$id?$m->find($id):null;if($id===null){$m->insert($input);$id=(int)$m->getInsertID();$action='created';}else{$m->update($id,$input);$action=($before['enrollment_status']??null)!==$input['enrollment_status']?'enrollment_status_changed':'updated';}(new StudentAuditLogModel())->insert(['admin_id'=>(int)session()->get('admin_id'),'student_id'=>$id,'action'=>$action,'before_values'=>$before?json_encode($this->auditFields($before),JSON_THROW_ON_ERROR):null,'after_values'=>json_encode($input,JSON_THROW_ON_ERROR),'created_at'=>gmdate('Y-m-d H:i:s')]);if(!$db->transStatus()||!$db->transCommit())throw new \RuntimeException('Student update failed.');}catch(\Throwable $e){$db->transRollback();throw $e;}return redirect()->to(site_url('admin/students/'.$id))->with('success','Student record saved.');}catch(DomainException $e){return redirect()->to(site_url($id?'admin/students/'.$id.'/edit':'admin/students/new'))->with('error',$e->getMessage())->with('student_form',$input);}}
 private function form(array $student,string $title,bool $readOnly=false): string{$flash=session()->getFlashdata('student_form');if(is_array($flash))$student=array_merge($student,$flash);return view('students/form',['title'=>$title,'student'=>$student,'readOnly'=>$readOnly]);} private function student(int $id):array{$s=(new StudentModel())->find($id);if(!$s)throw PageNotFoundException::forPageNotFound('Student not found.');return $s;}
 private function input():array{$p=$this->request->getPost();$v=static fn(string $k,int $max=150):string=>is_string($p[$k]??null)?trim(mb_substr($p[$k],0,$max)):'';return ['student_id'=>$v('student_id',30),'full_name'=>$v('full_name'),'institutional_email'=>strtolower($v('institutional_email')),'program'=>$v('program',100),'program_code'=>$v('program_code',30)?:null,'specialization'=>$v('specialization')?:null,'department'=>$v('department',100),'enrollment_status'=>$v('enrollment_status',20)];}
 private function validateInput(array $d,?int $id):void{if($d['student_id']===''||preg_match('/\A[A-Za-z0-9-]{1,30}\z/',$d['student_id'])!==1||$d['full_name']===''||$d['program']===''||$d['department']===''||filter_var($d['institutional_email'],FILTER_VALIDATE_EMAIL)===false||!in_array($d['enrollment_status'],['enrolled','not_enrolled'],true))throw new DomainException('Complete all required fields with valid values.');$m=new StudentModel();foreach(['student_id','institutional_email'] as $f){$e=$m->where($f,$d[$f])->first();if($e&&($id===null||(int)$e['id']!==$id))throw new DomainException(ucwords(str_replace('_',' ',$f)).' is already in use.');}}
 private function auditFields(array $s):array{return array_intersect_key($s,array_flip(['student_id','full_name','institutional_email','program','program_code','specialization','department','enrollment_status']));}}
